import re

def parse_duration(s):
    s = s.strip()
    if not s:
        raise ValueError("empty string")

    # Colon format: mm:ss or hh:mm:ss
    if ':' in s:
        parts = s.split(':')
        if len(parts) not in (2, 3):
            raise ValueError("invalid colon format")
        for p in parts:
            if not p:
                raise ValueError("empty part in colon format")
        try:
            nums = [int(p) for p in parts]
        except ValueError:
            raise ValueError("non-integer in colon format")
        if len(nums) == 2:
            minutes, seconds = nums
            return minutes * 60 + seconds
        else:
            hours, minutes, seconds = nums
            return hours * 3600 + minutes * 60 + seconds

    # Bare integer (no unit letters, no colon)
    if re.match(r'^\d+$', s):
        return int(s)

    # Unit-based format: must contain at least one unit letter
    if not re.search(r'[hms]', s, re.IGNORECASE):
        raise ValueError("invalid format")

    # Validate overall structure: alternating number+unit, nothing else
    if not re.match(r'^(\d+(?:\.\d+)?[hms])+$', s, re.IGNORECASE):
        raise ValueError("invalid format")

    unit_order = {'h': 0, 'm': 1, 's': 2}
    seen_units = set()
    last_order = -1
    total_seconds = 0.0

    for match in re.finditer(r'(\d+(?:\.\d+)?)([hms])', s, re.IGNORECASE):
        num_str = match.group(1)
        unit = match.group(2).lower()

        if unit in seen_units:
            raise ValueError(f"duplicate unit '{unit}'")
        seen_units.add(unit)

        order = unit_order[unit]
        if order <= last_order:
            raise ValueError("units not in descending order (h > m > s)")
        last_order = order

        try:
            num = float(num_str)
        except ValueError:
            raise ValueError(f"invalid number '{num_str}'")

        if unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        else:
            total_seconds += num

    return int(total_seconds)

